function closeAll() {
            var sidebar = document.getElementById('sidebar');
            var sidebarToggle = document.getElementById('sidebarToggle');
            var calendarPopup = document.getElementById('calendarPopup');
            var calendarToggle = document.getElementById('calendarToggle');
            var loginPopup = document.getElementById('loginPopup');
            var loginToggle = document.getElementById('loginToggle');
            var searchPopup = document.getElementById('searchPopup');
            var searchToggle = document.getElementById('searchToggle');
            var overlay = document.getElementById('overlay');
            var toggles = document.getElementsByClassName('toggle');
            var popups = document.getElementsByClassName('popup');

            if (calendarToggle.className === 'toggle shift active') {
                calendarToggle.className = 'toggle shift';
                calendarPopup.className = 'popup'
                overlay.className = 'show';
            } else {
                overlay.className = 'hide';

                sidebarToggle.className = 'toggle';
                sidebar.className = 'popup';

                calendarToggle.className = 'toggle';
                calendarPopup.className = 'popup';

                searchToggle.className = 'toggle';
                searchPopup.className = 'popup';

                loginToggle.className = 'toggle';
                loginPopup.className = 'popup';
            }
        }

function sidebarToggle() {
            var sidebar = document.getElementById('sidebar');
            var sidebarToggle = document.getElementById('sidebarToggle');
            var calendarPopup = document.getElementById('calendarPopup');
            var calendarToggle = document.getElementById('calendarToggle');
            var loginPopup = document.getElementById('loginPopup');
            var loginToggle = document.getElementById('loginToggle');
            var searchPopup = document.getElementById('searchPopup');
            var searchToggle = document.getElementById('searchToggle');
            var overlay = document.getElementById('overlay');
            var toggles = document.getElementsByClassName('toggle');
            var popups = document.getElementsByClassName('popup');

            //overlay 
            if (overlay.className === 'hide') {
                overlay.className = 'show';
            } else {
                overlay.className = 'hide';
            }

            if (sidebar.className === 'popup') {
                sidebar.className += ' active';
            } else {
                sidebar.className = 'popup';
            }

            if (sidebarToggle.className === 'toggle') {
                sidebarToggle.className += ' active';

            } else {
                sidebarToggle.className = 'toggle';
            }

            //calendar toggle shift
            if (calendarToggle.className === 'toggle' || calendarToggle.className === 'toggle active') {
                calendarToggle.className = 'toggle shift';
            } else {
                calendarToggle.className = 'toggle';
            }

            //OTHER TOGGLES
            // login shift is sidebar is open
            if (sidebarToggle.className === 'toggle active' & loginToggle.className === 'toggle shift') {
                loginToggle.className = 'toggle shift';

                //if not open
            } else if (sidebarToggle.className === 'toggle' & loginToggle.className === 'toggle shift') {
                loginToggle.className = 'toggle';
                //if nothing is open
            } else if (loginToggle.className === 'toggle' || loginToggle.className === 'toggle active') {
                loginToggle.className = 'toggle shift';
                loginPopup.className = 'popup';
                overlay.className = 'show';
                //if login is active
            } else {
                loginToggle.className = 'toggle';
            }

            // search shift is sidebar is open
            if (sidebarToggle.className === 'toggle active' & searchToggle.className === 'toggle shift') {
                searchToggle.className = 'toggle shift';

                //if not open
            } else if (sidebarToggle.className === 'toggle' & searchToggle.className === 'toggle shift') {
                searchToggle.className = 'toggle';
                //if nothing is open
            } else if (searchToggle.className === 'toggle' || searchToggle.className === 'toggle active') {
                searchToggle.className = 'toggle shift';
                searchPopup.className = 'popup';
                //if search is active
            } else {
                searchToggle.className = 'toggle';
            }
        }

/* ========== HEADER COMPONENTS ========== */
#overlay.hide {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 20px;
  background-color: transparent;
  z-index: 10;
  opacity: .3;
  display: flex;
  transition: var(--short-out);
}

#overlay.show {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background-color: #001226;
  z-index: -10;
  opacity: .65;
  transition: var(--short-in);
}

#secret-logo {
  width: 50px;
  margin: auto;
  padding: 5px;
  transform: translate(0, -100%);
  opacity: 0;
  transition: all 500ms ease-out 500ms;
}

#overlay.hide:hover #secret-logo {
  transform: translate(0, 0);
  width: 75px;
  opacity: 1;
  transition: all 500ms ease-in 500ms;
  transition-delay: 0;
}

#overlay.hide #secret-logo:hover {
  transform: translate(0, 0);
  width: 100px;
  opacity: 1;
  transition: all 500ms ease-in 200ms;
}

/*----------ALL TOGGLES------------*/
.toggle {
  position: fixed;
  cursor: pointer;
  z-index: var(--toggle-index);
  display: flex;
  align-content: center;
  height: var(--toggle-height);
  width: var(--toggle-width);
  padding: 0;
  transform-origin: center;
  margin: 0;
  /* background-color: rgba(255, 253, 247, 0.5); */
  transition: var(--toggle-out);
}

.toggle.active {
  position: fixed;
  background-color: transparent;
  transform: var(--flip);
  perspective: var(--flip-perspective);
  transform-origin: var(--flip-tranform-origin);
  transform-style: var(--flip-transform-style);

}

.toggle:hover {
  height: calc(var(--toggle-height) + 16px);
  /* background-color: var(--white-rgba); */
  transition: var(--toggle-in);
}

.toggle.active:hover {
  height: var(--toggle-height);
  width: var(--toggle-width);
  background-color: transparent;
}

/*TOGGLE ICONS*/
.toggle svg {
  fill: #fed318;
  height: var(--toggle-height);
  width: var(--toggle-width);
  overflow: visible;
  transition: var(--toggle-out);
}

.active svg {
  stroke-width: 0;
  transition: var(--toggle-out);
}

.toggle:hover svg {
  fill: #d72b88;
  background-color: transparent;
  transform: scale(.8);
  transition: var(--toggle-in);
}

.toggle.active:hover svg {
  transform: scale(.8);
  transition: var(--toggle-in);
}

.toggle svg .fill {
  fill: none;
  opacity: 0;
  transform: scale(1);
  stroke-width: 0;
  transform-origin: center;
  transition: var(--toggle-out), var(--opacity-instant);
}

.toggle.active svg .fill {
  fill: #fffdf7;
  stroke-width: 0;
  box-shadow: rgba(17, 17, 26, 0.1) 0px 0px 16px;
  opacity: 1;
  transition: var(--toggle-in);
}

.toggle.active:hover svg .fill {
  fill: #d72b88;
  stroke: #d72b88;
  box-shadow: rgba(17, 17, 26, 0.1) 0px 0px 16px;
  opacity: 1;
  transition: var(--toggle-in);
}

.toggle .icon {
  opacity: 1;
  transition: var(--toggle-out);

}

.toggle.active .icon {
  opacity: 0;
  transition: var(--toggle-in);
}

.toggle .x {
  opacity: 0;
  transition: var(--toggle-out);
}

.toggle.active .x {
  opacity: 1;
  fill: #fed318;
  background-color: transparent;
  transition: var(--toggle-in);
  stroke: none !important;
}

.active:hover .x {
  opacity: 1;
  fill: rgba(254, 211, 24, .5), #fed318;
  background-color: transparent;
  transition: var(--toggle-in);
}

.active .outline {
  stroke: none !important;
}

/*TEXT*/
.toggle .text {
  position: absolute;
  border-radius: 5px;
  text-align: center;
  margin: auto;
  opacity: 0;
  width: var(--toggle-width);
  bottom: 0;


  padding: 0px 2px 0px 2px;
  border-radius: 3px;
  /*background-color:  rgba(255, 255, 255, .5);*/
  transition: var(--label-out), var(--opacity-instant);

  /*test*/
  -webkit-text-fill-color: #fffdf7;
  /* Will override color (regardless of order) */
  -webkit-text-stroke-width: .75px;
  -webkit-text-stroke-color: #001226;
}

.toggle span {
  color: #001226;
  opacity: 1;
  text-transform: uppercase;
  font-family: var(--new-order);
  font-weight: 600;
  font-size: 18px;
  stroke: .25px;
  stroke-color: white;
}

.shift.active .text,
.active .text {
  opacity: 0;
  transition: none;
}

.toggle:hover .text {
  opacity: 1;
  transition: var(--label-drop);
}

.toggle.active:hover .text {
  opacity: 0;
}


/*------------ALL POPUPS------------*/
.popup {
  box-sizing: border-box;
  position: fixed;
  background-color: #031842;
  transition: var(--toggle-out);
}

.popup.active {
  z-index: -1;
  box-shadow: rgba(17, 17, 26, 0.1) 0px 8px 24px, rgba(17, 17, 26, 0.1) 0px 16px 56px, rgba(17, 17, 26, 0.1) 0px 24px 80px;

  transition: var(--toggle-in);
}

/*========= FLOATING SEARCH =========*/
#floatingSearch {
  position: fixed;
  width: fit-content;
  display: flex;
  flex-direction: column;
  justify-content: flex-start;
  align-content: right;
  top: 0;
  right: 0;
  border-radius: 5px;
  /* z-index: var(--float-index); */
}

/*SEARCH TOGGLE*/

#searchToggle {
  border-radius: var(--top-right-br);

  top: 3px;
  right: 0;
  z-index: -1;
  transition: var(--toggle-out);
}

#searchToggle:hover {}

#searchToggle .text span {
  margin-right: 5px;
}

#searchToggle.active.shift,
#searchToggle.active {
  margin-top: 5px;
  background-color: transparent;
  border-radius: var(--top-left-br);

  transform: scale(.8);
  right: calc(var(--search-width));
  transition: var(--toggle-out);
}

#searchToggle.active:hover {
  background-color: transparent;
  border-radius: var(--top-left-br);
  transition: var(--toggle-in);
}

#searchToggle svg {
  transform: scale(1.3);
  transition: var(--toggle-out);
  transition-delay: 400ms;
}

#searchToggle:hover svg {
  fill: #d72b88;
  transform: scale(1);
  transition: var(--toggle-in);
}

#searchToggle.active svg {
  width: var(--toggle-width);
  height: var(--toggle-height);
  position: absolute;
  top: 0;
  right: 0;
  fill: #001226;
  text-align: center;
  transition: var(--toggle-out);
}


/*SEARCH POPUP*/
#searchPopup {
  height: auto;
  width: var(--search-width);
  top: 0;
  right: 0;
  padding: 15px 0 15px 15px;
  z-index: 1;
  border-radius: 0 0 0 5px;
  transform: translate(100%, 0);
  transition: var(--toggle-out);
}

#searchPopup.active {

  transform: translate(0, 0);
}

#searchPopup form {
  margin: auto;
  position: relative;
  height: 2rem;
  border-radius: 50%;
  border: none;
  z-index: 1;
  box-sizing: border-box;
  width: 100%;
  cursor: pointer;
  border-radius: 2px;
  border: var(--outline-width) solid #001226;
  opacity: 1;
  background-color: #fffdf7;
  transition: var(--toggle-in);
}

#searchPopup form input {
  font-family: 'new-order', serif;
  position: absolute;
  font-weight: 400;
  color: #243f76;
  top: 0;
  font-size: 1rem;
  padding: 0 5px;
  width: 100%;
  height: 100%;
  border-radius: 5px 0 0 5px;
  border: none;
  transition: var(--toggle-out);
  transition-delay: 1000ms;
  z-index: 0;
}

#floatingSearch form:focus input,
#floatingSearch form:valid input {
  display: block;
  border: none;
  border-radius: 5px;
  color: #243f76;
  opacity: 1;
  transition: var(--toggle-in);
  background-color: var(--white-rgba);
}

#floatingSearch input::-webkit-search-cancel-button {
  -webkit-appearance: none;
}

#floatingSearch *:focus {
  outline: none;
}

/*========= FLOATING LOGIN =========*/
#floatingLogin {
  position: fixed;
  display: flex;
  border-radius: var(--top-right-br);
  flex-direction: column;
  justify-content: flex-start;
  right: 0;
  align-content: flex-start;
  /* z-index: var(--float-index); */
}

/*LOGIN TOGGLE*/
#loginToggle {
  justify-content: center;
  top: calc(var(--toggle-height) + 16px);
  border-radius: var(--right-br);
  padding: 1px 0px 1px 0;
  /* position: fixed; */
  right: 0;
  z-index: -1;
  animation: enterRight 200ms ease-in 100ms;
  transition: var(--toggle-out), var(--opacity-instant);
}

#loginToggle:hover {
  justify-content: center;
  height: calc(var(--toggle-height) + 34px);
  width: calc(var(--toggle-width) * 1);
}

#loginToggle.active {
  top: 0;
  right: calc(var(--login-width));
  transition: var(--toggle-in);
}

#searchToggle.shift,
#loginToggle.shift {
  opacity: 0;
  transform: translate(100%, 0);
  transition: var(--toggle-out);
}

#loginToggle .text {
  width: 110%;
  line-height: 18px;
  font-size: 18px;
  position: absolute;
  bottom: 0;
  right: 0;
}

#loginToggle .text span {
  line-height: 9px;
  font-size: 18px;
}

/*LOGIN POPUP*/
#loginPopup {

  height: auto;
  width: var(--login-width);
  top: 0;
  border-radius: var(--top-right-br);
  right: 0;
  padding: 20px 20px 20px 40px;
  overflow: hidden;
  transform: translate(100%, 0);
  transition: var(--toggle-out);
}

#loginPopup.active {
  transform: translate(0, 0);
}

/* ----- FLOATING CALENDAR ------ */

#floatingCalendar {
  position: fixed;
  /* top: calc(var(--toggle-height) + 14px); */
  left: 0;
  /* z-index: var(--float-index); */
}

#calendarToggle {
  /* position: fixed; */
  top: calc(var(--toggle-height) + 10px);
  left: 0;
  border-radius: var(--left-br);
  z-index: -1;
  padding: 5px 0 5px 0px;
}

#calendarToggle:hover {
  /* position: fixed; */
  height: calc(var(--toggle-height) * 1.5);
}

#calendarToggle.active {
  transform: translate(0, 0), rotate(0);
  top: 0;
  left: calc(var(--floating-calendar-width));
}

/*when calendar & menu are active*/
#calendarToggle.active.shift {
  z-index: 1;
  left: calc(var(--floating-calendar-width));
  top: -2px;
  position: fixed;
  padding: 0 3px 5px 0;
  border-radius: var(--right-br);
  /* position: absolute; */
  transition: var(--toggle-in);
}

/*when menu is active*/
#calendarToggle.shift {
  position: fixed;
  left: calc(var(--sidebar-width));
  /* position: absolute; */
  padding-left: 0;
  transition: var(--toggle-in);
  background-color: transparent;
}

#calendarToggle.shift svg {
  transition: var(--toggle-in);
}



#calendarToggle.active.shift svg .fill {
  fill: #031842;
  opacity: 1;
  transition: var(--toggle-in);
}

#calendarToggle:hover svg {
  fill: #d72b88;
  transform: scale(.85) !important;
  transition: var(--toggle-in);
}

#calendarToggle .text {
  transform: translate(0, -15px);
  transition: var(--label-out);
}

#calendarToggle:hover .text {
  transform: translate(0, 0);
  transition: var(--label-drop);
}

#calendarPopup {
  top: 0;
  left: 0;
  padding: 20px 0;
  height: var(--floating-calendar-height);
  width: var(--floating-calendar-width);
  transform: translate(-100%, 0);
  margin: 0;
  overflow: hidden;
  display: flex;
  justify-content: center;
  flex-wrap: wrap;
  flex-direction: row;
  align-content: flex-start;
}

#calendarPopup.active {
  transform: translate(0, 0);
}

/*CM Widget*/
#cm-widget-wrap {
  height: calc(100vh - 200px);
  overflow-y: scroll;
}

#cm-widget-wrap::-webkit-scrollbar-track {
  -webkit-box-shadow: inset 0 0 6px rgba(0, 0, 0, 0.3);
  background-color: #243f76;
}

#cm-widget-wrap::-webkit-scrollbar {
  width: 10px;
  background-color: #243f76;
}

#cm-widget-wrap::-webkit-scrollbar-thumb {
  background-color: #fed318;
}

/*popup styling*/
#calendarPopup h2 {
  font-size: 1.5rem;
  font-family: var(--new-order);
  color: #fffdf7;
  text-transform: uppercase;
  text-align: center;
}

#calendar-link {
  position: absolute;
  bottom: 0;
  width: 300px;
  border-radius: 3px;
  display: flex;
  margin: 10px auto;
  text-align: center;
  /* height: 50px; */
}

#calendar-link:hover {
  cursor: pointer;
}

#calendar-link span {
  text-transform: uppercase;
  color: #243f76;
  font-size: 1rem;
  font-family: var(--new-order);
  text-decoration: none !important;
  font-weight: 400;
  margin: 10px auto;
  width: 100%;
  text-align: center;
}

#calendar-link:hover span {
  color: #fffdf7;
}


#calendarPopup .button {}

