/* =============== MOBILE HEADER =============== */
@media only screen and (max-width: 640px) {

  #floatingCalendar {
    position: fixed;
    top: calc(var(--toggle-width) * 1 + 1rem);
    left: 0;
    z-index: 5;
  }

  #floatingSearch {
    position: fixed;
    left: 0;
    top: calc(var(--toggle-width) * 2 + 2.5rem);
  }

  #floatingLogin {
    position: fixed;
    left: 0;
    top: calc(var(--toggle-width) * 3 + 3rem);
    z-index: 4;
  }

  /*popups*/
  .popup {
    z-index: -1;
  }

  .popup.active {
    z-index: 1;
  }

  /*====TOGGLES===*/

  /*SIDEBAR*/
  #sidebarToggle {
    transform: translate(5px, 0);
  }

  /*CALENDAR*/
  #calendarToggle {
    position: fixed;
    top: calc(var(--toggle-width) * 1 + 1rem);
    left: 5px;
    z-index: 5;
    opacity: 0;
    transform: translate(-100%, 0);
    transition: var(--toggle-out);
  }

  #calendarToggle.shift {
    position: fixed;
    top: calc(var(--toggle-width) * 1 + 1rem);
    left: calc(var(--sidebar-width) + 5px);
    opacity: 1;
    transform: translate(0, 0);
    transition: var(--toggle-in);
    transition-delay: 200ms;
  }

  /*SEARCH*/
  #searchToggle {
    position: fixed;
    top: calc(var(--toggle-width) * 2 + 3rem);
    left: 12px;
    opacity: 0;
    transform: translate(-120%, 0);
    transition: var(--toggle-out);
  }

  #searchToggle.shift {
    position: fixed;
    transform: translate(0, 0);
    left: calc(var(--sidebar-width) + 12px);
    opacity: 1;
    transition: var(--toggle-in);
    transition-delay: 250ms;
  }

  #searchToggle.active {
    top: 15px;
    transform: translate(0, 0);
    left: calc(100vw - var(--toggle-width) - 5px);
  }

  /*LOGIN*/
  #loginToggle {
    position: fixed;
    top: calc(var(--toggle-width) * 3 + 40px);
    left: 5px;
    z-index: 4;
    opacity: 0;
    transform: translate(-100%, 0);
    transition: var(--toggle-out);

  }

  #loginToggle.shift {
    position: fixed;
    left: calc(var(--sidebar-width) + 5px);
    opacity: 1;
    transition: var(--toggle-in);
    transform: translate(0, 0);
    transition-delay: 300ms;
  }

  #loginToggle.active {
    top: 5px;
    left: calc(100vw - var(--toggle-width) - 5px);
    transform: translate(0, 0);
    transition-delay: 0;
  }

  /*TEXT*/
  .toggle.shift .text {
    position: fixed;
    border-radius: 5px;
    text-align: center;
    margin: auto;
    opacity: 0;
    width: fit-content;
    bottom: 0;


    padding: 5px 2px 2px 2px;
    border-radius: 3px;
    transition: var(--label-out), var(--opacity-instant);
  }



  .shift.active .text,
  .active .text {
    opacity: 0;
    transition: none;
  }

  .toggle:hover .text {
    opacity: 1;
    transition: var(--label-drop);
  }

  .toggle.active:hover .text {
    opacity: 0;
  }

  .toggle.shift .text,
  .toggle:hover .text {
    opacity: 1;
    transform: scale(1);
    bottom: -5rem;
    transition: var(--label-drop);
    transform: translate(0, 0);
    left: 0;
  }


  .toggle span {
    color: #001226;
    opacity: 1;
    text-transform: uppercase;
    font-family: var(--new-order);
    font-weight: 600;
    font-size: 18px;
    padding: 5px 5px 2px 5px;
    border-radius: 3px;
  }

  #sidebarToggle:hover .text {
    bottom: 0;
  }

  #calendarToggle.shift .text {
    width: fit-content;
    height: fit-content;
    transform: translate(0, 10px);
    top: 0;
    padding: 5px 5px 2px 0px;
  }

  #calendarToggle.shift:hover .text {
    width: fit-content;
    top: 0;
    right: 0;
    padding: 5px 5px 2px 0px;
    transform: translate(0, 10px);
  }

  #searchToggle.shift .text {
    width: fit-content;
    height: fit-content;
    bottom: -30%;
    left: 0;
    transform: translate(-10px, 0px);
    text-align: left !important;
  }

  #searchToggle.shift:hover .text {
    width: fit-content;
    transform: translate(0px, 0px);
    padding: 5px 5px 2px 0px;
  }

  #loginToggle.shift .text {
    width: fit-content;
    height: fit-content;
    bottom: 0;
    transform: translate(0, 100%);
    padding: 5px 5px 2px 0px;
  }

  #loginToggle.shift:hover .text {
    width: fit-content;
    padding: 5px 5px 2px 0px;
    transform: translate(0, 0);
  }

  #calendarToggle.active .text,
  #loginToggle.active .text,
