function calendarToggle() {
            var sidebar = document.getElementById('sidebar');
            var sidebarToggle = document.getElementById('sidebarToggle');
            var calendarPopup = document.getElementById('calendarPopup');
            var calendarToggle = document.getElementById('calendarToggle');
            var loginPopup = document.getElementById('loginPopup');
            var loginToggle = document.getElementById('loginToggle');
            var searchPopup = document.getElementById('searchPopup');
            var searchToggle = document.getElementById('searchToggle');
            var overlay = document.getElementById('overlay');

            //overlay 
            if (overlay.className === 'hide') {
                overlay.className = 'show';
            } else {
                overlay.className = 'hide';
            }
            //popup 
            if (calendarPopup.className === 'popup') {
                calendarPopup.className += ' active';
            } else {
                calendarPopup.className = 'popup';
            }

            //toggle
            if (calendarToggle.className === 'toggle' || calendarToggle.className === 'toggle shift') {
                calendarToggle.className += ' active';
                overlay.className = 'show';
            } else if (calendarToggle.className === 'toggle shift active') {
                calendarToggle.className = 'toggle shift';
                overlay.className = 'show';
            }
            else {
                calendarToggle.className = 'toggle';
            }


            //OTHER TOGGLES
            // login shift is sidebar is open
            if (sidebarToggle.className === 'toggle active' & loginToggle.className === 'toggle shift') {
                loginToggle.className = 'toggle shift';

                //if not open
            } else if (sidebarToggle.className === 'toggle' & loginToggle.className === 'toggle shift') {
                loginToggle.className = 'toggle';
                //if nothing is open
            } else if (loginToggle.className === 'toggle' || loginToggle.className === 'toggle active') {
                loginToggle.className = 'toggle shift';
                loginPopup.className = 'popup';
                overlay.className = 'show';
                //if login is active
            } else {
                loginToggle.className = 'toggle';
            }

            // search shift is sidebar is open
            if (sidebarToggle.className === 'toggle active' & searchToggle.className === 'toggle shift') {
                searchToggle.className = 'toggle shift';

                //if not open
            } else if (sidebarToggle.className === 'toggle' & searchToggle.className === 'toggle shift') {
                searchToggle.className = 'toggle';
                //if nothing is open
            } else if (searchToggle.className === 'toggle' || searchToggle.className === 'toggle active') {
                searchToggle.className = 'toggle shift';
                searchPopup.className = 'popup';
                //if search is active
            } else {
                searchToggle.className = 'toggle';
            }

        }

