  font-weight: 400;
  margin: 10px auto;
  width: 100%;
  text-align: center;
}

#calendar-link:hover span {
  color: #fffdf7;
}


#calendarPopup .button {}

/* ----- SIDEBAR TOGGLE ----- */
#sidebarWrap {
  position: fixed;
  top: 0;
  left: 0;
  /* z-index: var(--float-index); */
  width: var(--sidebar-width);
}

/*TOGGLE*/
#sidebarToggle {
  border-radius: var(--top-left-br);
