  transition: var(--short-out);
  transition-delay: 1000ms;
}

#sidebar-search form input {
  font-family: 'new-order', serif;
  position: absolute;
  font-weight: 400;
  color: #243f76;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  font-size: 1rem;
  border: none;
  padding: .2rem;
  opacity: 0;
  transition: var(--short-out);
  transition-delay: 1000ms;
  z-index: 0;
}

#sidebar-search svg {
  box-sizing: border-box;
  width: 1.5rem;
  height: 1.5rem;
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  text-align: center;
  transition: var(--short-out);
  transition-delay: 1000ms;
}

#sidebar-search svg path {
