  opacity: 1;
  transition: var(--short-in), width 300ms ease-in 200ms;
  padding: 0 5px;
  background-color: rgba(255, 253, 247, 1);

}

#sidebar-search form:hover svg,
#sidebar-search form:valid svg {
  left: 92%;
  transition: var(--short-in)
}

#sidebar-search form:hover svg path,
#sidebar-search form:valid svg path {
  fill: #001226;
  transition: var(--short-in)
}

#sidebar-search *:focus {
  outline: none;
}

#sidebar-search form svg:hover {
  width: 1.75rem;
  transition: all 200ms ease-in, width 300ms ease-in 200ms;
