#login:hover a {
  font-weight: 400;
  text-align: center;
  color: #001226 !important;
  font-weight: 500;
  letter-spacing: 3px;
  box-shadow: var(--btn-hover-box-shadow);
  background-color: #fffdf7;
  transition: var(--btn-out), box-shadow 200ms ease 200ms;

}

/* =============== MOBILE HEADER =============== */
@media only screen and (max-width: 640px) {

  #floatingCalendar {
    position: fixed;
    top: calc(var(--toggle-width) * 1 + 1rem);
    left: 0;
    z-index: 5;
  }

  #floatingSearch {
    position: fixed;
    left: 0;
    top: calc(var(--toggle-width) * 2 + 2.5rem);
  }

  #floatingLogin {
    position: fixed;
    left: 0;
    top: calc(var(--toggle-width) * 3 + 3rem);
    z-index: 4;
  }

  /*popups*/
  .popup {
    z-index: -1;
  }

  .popup.active {
    z-index: 1;
  }

  /*====TOGGLES===*/

  /*SIDEBAR*/
  #sidebarToggle {
    transform: translate(5px, 0);
  }

  /*CALENDAR*/
  #calendarToggle {
    position: fixed;
    top: calc(var(--toggle-width) * 1 + 1rem);
    left: 5px;
    z-index: 5;
    opacity: 0;
    transform: translate(-100%, 0);
    transition: var(--toggle-out);
  }

  #calendarToggle.shift {
    position: fixed;
    top: calc(var(--toggle-width) * 1 + 1rem);
    left: calc(var(--sidebar-width) + 5px);
    opacity: 1;
    transform: translate(0, 0);
    transition: var(--toggle-in);
    transition-delay: 200ms;
  }

  /*SEARCH*/
  #searchToggle {
    position: fixed;
    top: calc(var(--toggle-width) * 2 + 3rem);
    left: 12px;
    opacity: 0;
    transform: translate(-120%, 0);
    transition: var(--toggle-out);
  }

  #searchToggle.shift {
    position: fixed;
    transform: translate(0, 0);
    left: calc(var(--sidebar-width) + 12px);
    opacity: 1;
    transition: var(--toggle-in);
    transition-delay: 250ms;
  }

  #searchToggle.active {
    top: 15px;
    transform: translate(0, 0);
    left: calc(100vw - var(--toggle-width) - 5px);
  }

  /*LOGIN*/
  #loginToggle {
    position: fixed;
    top: calc(var(--toggle-width) * 3 + 40px);
    left: 5px;
    z-index: 4;
    opacity: 0;
    transform: translate(-100%, 0);
    transition: var(--toggle-out);

  }

  #loginToggle.shift {
    position: fixed;
    left: calc(var(--sidebar-width) + 5px);
    opacity: 1;
    transition: var(--toggle-in);
    transform: translate(0, 0);
    transition-delay: 300ms;
  }

  #loginToggle.active {
    top: 5px;
    left: calc(100vw - var(--toggle-width) - 5px);
    transform: translate(0, 0);
    transition-delay: 0;
  }

  /*TEXT*/
  .toggle.shift .text {
    position: fixed;
    border-radius: 5px;
    text-align: center;
    margin: auto;
    opacity: 0;
    width: fit-content;
    bottom: 0;


    padding: 5px 2px 2px 2px;
    border-radius: 3px;
    transition: var(--label-out), var(--opacity-instant);
  }



  .shift.active .text,
  .active .text {
    opacity: 0;
    transition: none;
  }

  .toggle:hover .text {
    opacity: 1;
    transition: var(--label-drop);
  }

  .toggle.active:hover .text {
    opacity: 0;
  }

  .toggle.shift .text,
  .toggle:hover .text {
    opacity: 1;
    transform: scale(1);
    bottom: -5rem;
    transition: var(--label-drop);
    transform: translate(0, 0);
    left: 0;
  }


  .toggle span {
    color: #001226;
    opacity: 1;
    text-transform: uppercase;
    font-family: var(--new-order);
    font-weight: 600;
    font-size: 18px;
    padding: 5px 5px 2px 5px;
    border-radius: 3px;
  }

  #sidebarToggle:hover .text {
    bottom: 0;
  }

  #calendarToggle.shift .text {
    width: fit-content;
    height: fit-content;
    transform: translate(0, 10px);
    top: 0;
    padding: 5px 5px 2px 0px;
  }

  #calendarToggle.shift:hover .text {
    width: fit-content;
    top: 0;
    right: 0;
    padding: 5px 5px 2px 0px;
    transform: translate(0, 10px);
  }

  #searchToggle.shift .text {
    width: fit-content;
    height: fit-content;
    bottom: -30%;
    left: 0;
    transform: translate(-10px, 0px);
    text-align: left !important;
  }

  #searchToggle.shift:hover .text {
    width: fit-content;
    transform: translate(0px, 0px);
    padding: 5px 5px 2px 0px;
  }

  #loginToggle.shift .text {
    width: fit-content;
    height: fit-content;
    bottom: 0;
    transform: translate(0, 100%);
    padding: 5px 5px 2px 0px;
  }

  #loginToggle.shift:hover .text {
    width: fit-content;
    padding: 5px 5px 2px 0px;
    transform: translate(0, 0);
  }

  #calendarToggle.active .text,
  #loginToggle.active .text,
  #searchToggle.active .text {
    opacity: 0;
    transition: none;
  }

  /*popups*/
  #calendarPopup {
    top: 0;
    left: 0;
    transform: translate(-100%, 0);
  }

  #calendarPopup.active {
    z-index: 1;
    transform: translate(0, 0);
  }

  #loginPopup.active {
    top: 0;
    right: 0;
  }

  /* MOBILE SIDEBAR */
  #sidebar-box {
    height: fit-content;
  }

  #logo {
    height: calc(var(--sidebar-logo-height) + 40px);

  }

  /* MOBILE LOGO */
  #animated-logo {
    margin: auto;
    width: 100%;
    height: var(--sidebar-logo-height);
    padding-top: 10px;
    transition: var(--short-in-out);
  }

  #animated-logo:hover {
    transform: scale(1.05);
    transition: var(--short-in-out);
  }

  /* MOBILE MENU */
  #homeLink,
  #joinLink {

    text-align: right;
  }

  .subtoggle {
    opacity: 0;
    height: calc(var(--menuitem-height) * 2);
    padding: 3px;
    margin: 2px;
  }

  .menuitem .sublabel {
    top: 0;
    left: 0;
    text-align: right;
  }

  .menuitem {
    height: fit-content;
    text-align: right;
    z-index: 0;
  }


  .menuitem input[type="checkbox"]:not(:checked)~label {
    z-index: -1;
  }

  .menuitem input[type="checkbox"]:not(:checked) {
    z-index: 1;
  }

  .menuitem input[type="checkbox"]:checked~a {
    z-index: 1;
  }

  .menuitem input[type="checkbox"]:checked~.menuitem input,
  .menuitem input[type="checkbox"]:checked~.menuitem label {
    z-index: -1;
  }

  .menuitem>a {
    text-align: right;
    font-size: 28px;
    line-height: 40px;
  }

  .submenuitem>a {
    font-size: 1rem;
    font-weight: 100;
    letter-spacing: 0;
    text-align: right;
  }

  .menuitem:hover>a {
    color: #fed318;
    letter-spacing: .1em;
  }

  .menuitem .submenuitem:hover>a {
    border-left: solid 0px #fffdf7;
  }

  /*SUBMENU*/

  .submenu ul {
    width: 100%;
    margin: 0px 10px 20px 0 !important;
    padding-right: 5px !important;
    border-right: solid 1px white;
    position: relative;
  }

  .submenu,
  .menuitem:hover .submenu,
  .menuitem .submenu:hover {
    opacity: 0;
    z-index: 0;
    margin: 0;
    position: relative;
    width: 100%;
    padding: 0;
    height: 0;
    left: -100%;
    top: 0;
  }

  #aboutToggle[type="checkbox"]:not(:checked)~#aboutSubmenu,
  #advocacyToggle[type="checkbox"]:not(:checked)~#advocacySubmenu,
  #membershipToggle[type="checkbox"]:not(:checked)~#membershipSubmenu,
  #eventsToggle[type="checkbox"]::not(:checked)~#eventsSubmenu {
    opacity: 0;
    height: 0;
    padding: 0 5px;
    margin: 10px 10px 20px 0;
    left: 10px;
  }

  #aboutToggle[type="checkbox"]:checked~#aboutSubmenu,
  #advocacyToggle[type="checkbox"]:checked~#advocacySubmenu,
  #membershipToggle[type="checkbox"]:checked~#membershipSubmenu,
  #eventsToggle[type="checkbox"]:checked~#eventsSubmenu {
    opacity: 1;
    height: fit-content;
    left: 0;
  }

  /* #aboutSubmenu,
  #membershipSubmenu,
  #advocacySubmenu,
  #eventsSubmenu {
    top: 0 !important;
  } */

  .homeLink,
  #joinLink,
  .sublabel {

    text-align: right;
  }

  #searchPopup {
    position: fixed;
    width: 0;
    border-radius: 3px;
    left: 100%;
    background-color: #031842;
    padding: 10px;
    margin: 10px var(--toggle-width) 0 10px;
  }

  #searchPopup.active {
    left: 0;
    width: calc(100vw - var(--toggle-width) * 1.5);
    border-radius: 3px;
    background-color: #031842;
    padding: 10px;
    margin: 10px var(--toggle-width) 0 10px;
  }

  /*SEARCH*/
  #searchPopup form {
    position: relative;
    height: 3rem;
    width: 100%;
    left: 0;
    border-color: #fffdf7;
    border-width: 1px;
  }

  /*hide sidebar search & login */
  #login,
  #sidebar-search {
    display: none;
  }
}

