.intro-block {
  width: var(--block-width);
  max-width: var(--block-width);
  margin: 0;
  padding: 0;
  height: var(--block-width);
  display: flex;
  flex-direction: column;
  align-content: flex-end;
  gap: 0;
  z-index: 10;
  justify-content: flex-end;
  transition: var(--intro-block-transition);
  overflow: hidden;
}


.intro-block img {
  width: 100%;
  height: 100%;
  transform: scale(1);
  z-index: -1;
}

.intro-block .ribbon {
  display: flex;
  margin: 0;
  flex-direction: row;
  padding: 0;
  align-content: center;
  justify-content: center;
  z-index: 4;
  list-style: none;
  padding: 5px 0px 0px 0px;
  width: var(--block-width);
  background-color: transperant;
  position: absolute;
  max-width: var(--block-width);
  transition: var(--intro-block-transition);
}

.intro-block:hover .ribbon {
  transition: var(--intro-block-transition);
  background-color: #031842;
}

.intro-block .ribbon .name,
.intro-block .ribbon .position {
  width: 100%;
  line-height: 1em;
  text-align: right !important;
  font-family: 'new-order', sans-serif;
  color: #fffdf7;
  z-index: 5;
  padding: 5px;
  letter-spacing: 0;
  transition: var(--intro-block-transition);
}

.intro-block span {

  text-align: right;
}

.intro-block .text {
  width: 100%;
  padding: 5px 0;
}

.intro-block .position {
  font-weight: 500 !important;
  font-size: 1rem;
  text-transform: uppercase;
  font-family: 'new-order', sans-serif !important;
    -webkit-text-stroke-width:.5px;
  -webkit-text-stroke-color: #031842;
text-shadow: 1px 1px 2px rgba(0,0,0,.6);
}

.intro-block .name {
  font-weight: 600;
  font-size: 1.25rem;
  font-family: 'new-order', sans-serif !important;

  -webkit-text-stroke-width:1px;
  -webkit-text-stroke-color: #031842;
}

.intro-block .icon {
  opacity: 0;
  margin: auto 10px auto 0;
  width: 0;
  transition: var(--intro-block-transition);
}

.intro-block .icon svg {
  height: 40px;
  fill: #fed318;
}

.intro-block:hover .icon {
  padding: 0;
  margin: auto 10px auto 0;
  opacity: 1;
  width: 3rem;
  transition: all 600ms ease-out 200ms, opacity 300ms ease 500ms;
}

.no-link .icon {
  opacity: 0;
  padding: 0 5px;
}

.intro-block:hover .title,
.intro-block:hover .name,
.intro-block:hover .position {
  padding-right: 1rem;

}

.no-link .intro-block:hover .icon {
  opacity: 0;
  width: 0;
}

.no-link .intro-block:hover .name,
.no-link .intro-block:hover .position {
  padding-right: 5px;

}

/* tablet */
@media screen and (max-width: 1024px) {

  .intro-block .ribbon .position {
    text-align: right;
    line-height: .8em;
  }

  .intro-block .ribbon .name {
    font-size: 1rem;
    padding-top: 2px;
    line-height: 1em;
  }

  .intro-block:hover .name,
  .intro-block:hover .position {
    padding-right: 5px;

  }

  .intro-block .ribbon {
    padding: 5px 0 0 0;
  }

  .intro-block:hover .icon,
  .intro-block .icon {
    opacity: 1;
    width: 3rem;
    padding: 5px;
    margin: auto;
  }

  .no-link .icon {
    opacity: 0;
    padding: 5px;
  }
}

/* mobile */
@media screen and (max-width: 640px) {
  .intro-block .icon {
    opacity: 1;
    transition: var(--intro-block-transition);
  }

  .intro-block .text {
    padding: 5px;
  }

  .no-link .icon {
    opacity: 0;
    width: 0;
    padding: 0;
  }
}

