:root {

    /* tracking in */
    --tracking-in-expand: tracking-in-expand;
    --tracking-in-expand-fwd: tracking-in-expand-fwd;
    --tracking-in-expand-fwd-top: tracking-in-expand-fwd-top;
    --tracking-in-expand-fwd-bottom: tracking-in-expand-fwd-bottom;
