    --text-shadow-pop-bl: text-shadow-pop-bl;
    --text-shadow-pop-left: text-shadow-pop-left;
    --text-shadow-pop-tl: text-shadow-pop-tl;
    /* pop up */
    --text-pop-up-top: text-pop-up-top;
    --text-pop-up-tr: text-pop-up-tr;
    --text-pop-up-right: text-pop-up-right;
