function calendarToggle() {
            var sidebar = document.getElementById('sidebar');
            var sidebarToggle = document.getElementById('sidebarToggle');
            var calendarPopup = document.getElementById('calendarPopup');
            var calendarToggle = document.getElementById('calendarToggle');
            var loginPopup = document.getElementById('loginPopup');
            var loginToggle = document.getElementById('loginToggle');
            var searchPopup = document.getElementById('searchPopup');
            var searchToggle = document.getElementById('searchToggle');
            var overlay = document.getElementById('overlay');

            //overlay 
            if (overlay.className === 'hide') {
                overlay.className = 'show';
            } else {
                overlay.className = 'hide';
            }
            //popup 
            if (calendarPopup.className === 'popup') {
                calendarPopup.className += ' active';
            } else {
                calendarPopup.className = 'popup';
            }

            //toggle
            if (calendarToggle.className === 'toggle' || calendarToggle.className === 'toggle shift') {
                calendarToggle.className += ' active';
                overlay.className = 'show';
            } else if (calendarToggle.className === 'toggle shift active') {
                calendarToggle.className = 'toggle shift';
                overlay.className = 'show';
            }
            else {
                calendarToggle.className = 'toggle';
            }


            //OTHER TOGGLES
            // login shift is sidebar is open
            if (sidebarToggle.className === 'toggle active' & loginToggle.className === 'toggle shift') {
                loginToggle.className = 'toggle shift';

                //if not open
            } else if (sidebarToggle.className === 'toggle' & loginToggle.className === 'toggle shift') {
                loginToggle.className = 'toggle';
                //if nothing is open
            } else if (loginToggle.className === 'toggle' || loginToggle.className === 'toggle active') {
                loginToggle.className = 'toggle shift';
                loginPopup.className = 'popup';
                overlay.className = 'show';
                //if login is active
            } else {
                loginToggle.className = 'toggle';
            }

            // search shift is sidebar is open
            if (sidebarToggle.className === 'toggle active' & searchToggle.className === 'toggle shift') {
                searchToggle.className = 'toggle shift';

                //if not open
            } else if (sidebarToggle.className === 'toggle' & searchToggle.className === 'toggle shift') {
                searchToggle.className = 'toggle';
                //if nothing is open
            } else if (searchToggle.className === 'toggle' || searchToggle.className === 'toggle active') {
                searchToggle.className = 'toggle shift';
                searchPopup.className = 'popup';
                //if search is active
            } else {
                searchToggle.className = 'toggle';
            }

        }

/* ========== HEADER COMPONENTS ========== */
#overlay.hide {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 20px;
  background-color: transparent;
  z-index: 10;
  opacity: .3;
  display: flex;
  transition: var(--short-out);
}

#overlay.show {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background-color: #001226;
  z-index: -10;
  opacity: .65;
  transition: var(--short-in);
}

/*----------ALL TOGGLES------------*/
.toggle {
  position: fixed;
  cursor: pointer;
  z-index: var(--toggle-index);
  display: flex;
  align-content: center;
  height: var(--toggle-height);
  width: var(--toggle-width);
  padding: 0;
  transform-origin: center;
  margin: 0;
  /* background-color: rgba(255, 253, 247, 0.5); */
  transition: var(--toggle-out);
}

.toggle.active {
  position: fixed;
  background-color: transparent;
  transform: var(--flip);
  perspective: var(--flip-perspective);
  transform-origin: var(--flip-tranform-origin);
  transform-style: var(--flip-transform-style);

}

.toggle:hover {
  height: calc(var(--toggle-height) + 16px);
  /* background-color: var(--white-rgba); */
  transition: var(--toggle-in);
}

.toggle.active:hover {
  height: var(--toggle-height);
  width: var(--toggle-width);
  background-color: transparent;
}

/*TOGGLE ICONS*/
.toggle svg {
  fill: #fed318;
  height: var(--toggle-height);
  width: var(--toggle-width);
  overflow: visible;
  transition: var(--toggle-out);
}

.active svg {
  stroke-width: 0;
  transition: var(--toggle-out);
}

.toggle:hover svg {
  fill: #d72b88;
  background-color: transparent;
  transform: scale(.8);
  transition: var(--toggle-in);
}

.toggle.active:hover svg {
  transform: scale(.8);
  transition: var(--toggle-in);
}

.toggle svg .fill {
  fill: none;
  opacity: 0;
  transform: scale(1);
  stroke-width: 0;
  transform-origin: center;
  transition: var(--toggle-out), var(--opacity-instant);
}

.toggle.active svg .fill {
  fill: #fffdf7;
  stroke-width: 0;
  box-shadow: rgba(17, 17, 26, 0.1) 0px 0px 16px;
  opacity: 1;
  transition: var(--toggle-in);
}

.toggle.active:hover svg .fill {
  fill: #d72b88;
  stroke: #d72b88;
  box-shadow: rgba(17, 17, 26, 0.1) 0px 0px 16px;
  opacity: 1;
  transition: var(--toggle-in);
}

.toggle .icon {
  opacity: 1;
  transition: var(--toggle-out);

}

.toggle.active .icon {
  opacity: 0;
  transition: var(--toggle-in);
}

.toggle .x {
  opacity: 0;
  transition: var(--toggle-out);
}

.toggle.active .x {
  opacity: 1;
  fill: #fed318;
  background-color: transparent;
  transition: var(--toggle-in);
  stroke: none !important;
}

.active:hover .x {
  opacity: 1;
  fill: rgba(254, 211, 24, .5), #fed318;
  background-color: transparent;
  transition: var(--toggle-in);
}

.active .outline {
  stroke: none !important;
}

/*TEXT*/
.toggle .text {
  position: absolute;
  border-radius: 5px;
  text-align: center;
  margin: auto;
  opacity: 0;
  width: var(--toggle-width);
  bottom: 0;


  padding: 0px 2px 0px 2px;
  border-radius: 3px;
  /*background-color:  rgba(255, 255, 255, .5);*/
  transition: var(--label-out), var(--opacity-instant);

  /*test*/
  -webkit-text-fill-color: #fffdf7;
  /* Will override color (regardless of order) */
  -webkit-text-stroke-width: .75px;
  -webkit-text-stroke-color: #001226;
}

.toggle span {
  color: #001226;
  opacity: 1;
  text-transform: uppercase;
  font-family: var(--new-order);
  font-weight: 600;
  font-size: 18px;
  stroke: .25px;
  stroke-color: white;
}

.shift.active .text,
.active .text {
  opacity: 0;
  transition: none;
}

.toggle:hover .text {
  opacity: 1;
  transition: var(--label-drop);
}

.toggle.active:hover .text {
  opacity: 0;
}


/*------------ALL POPUPS------------*/
.popup {
  box-sizing: border-box;
  position: fixed;
  background-color: #031842;
  transition: var(--toggle-out);
}

.popup.active {
  z-index: -1;
  box-shadow: rgba(17, 17, 26, 0.1) 0px 8px 24px, rgba(17, 17, 26, 0.1) 0px 16px 56px, rgba(17, 17, 26, 0.1) 0px 24px 80px;

  transition: var(--toggle-in);
}

