  width: calc(var(--toggle-width) * 1);
}

#loginToggle.active {
  top: 0;
  right: calc(var(--login-width));
  transition: var(--toggle-in);
}

#searchToggle.shift,
#loginToggle.shift {
  opacity: 0;
  transform: translate(100%, 0);
  transition: var(--toggle-out);
}

#loginToggle .text {
  width: 110%;
  line-height: 18px;
  font-size: 18px;
  position: absolute;
  bottom: 0;
  right: 0;
}

#loginToggle .text span {
  line-height: 9px;
