  top: 0;
  left: 0;
  padding: 20px 0;
  height: var(--floating-calendar-height);
  width: var(--floating-calendar-width);
  transform: translate(-100%, 0);
  margin: 0;
  overflow: hidden;
  display: flex;
  justify-content: center;
  flex-wrap: wrap;
  flex-direction: row;
  align-content: flex-start;
}

#calendarPopup.active {
  transform: translate(0, 0);
}

/*CM Widget*/
#cm-widget-wrap {
  height: calc(100vh - 200px);
  overflow-y: scroll;
}

#cm-widget-wrap::-webkit-scrollbar-track {
  -webkit-box-shadow: inset 0 0 6px rgba(0, 0, 0, 0.3);
  background-color: #243f76;
}

#cm-widget-wrap::-webkit-scrollbar {
  width: 10px;
  background-color: #243f76;
}

#cm-widget-wrap::-webkit-scrollbar-thumb {
  background-color: #fed318;
}

/*popup styling*/
#calendarPopup h2 {
  font-size: 1.5rem;
  font-family: var(--new-order);
  color: #fffdf7;
  text-transform: uppercase;
  text-align: center;
}

#calendar-link {
  position: absolute;
  bottom: 0;
  width: 300px;
  border-radius: 3px;
  display: flex;
  margin: 10px auto;
  text-align: center;
  /* height: 50px; */
}

#calendar-link:hover {
  cursor: pointer;
}

#calendar-link span {
  text-transform: uppercase;
  color: #243f76;
  font-size: 1rem;
  font-family: var(--new-order);
  text-decoration: none !important;
  font-weight: 400;
  margin: 10px auto;
  width: 100%;
  text-align: center;
}

#calendar-link:hover span {
  color: #fffdf7;
}


#calendarPopup .button {}

/* ----- SIDEBAR TOGGLE ----- */
#sidebarWrap {
  position: fixed;
  top: 0;
  left: 0;
  /* z-index: var(--float-index); */
  width: var(--sidebar-width);
}

/*TOGGLE*/
#sidebarToggle {
  border-radius: var(--top-left-br);
  top: 0;
  left: 0;
  transition: var(--toggle-out);
}


#sidebarToggle.active {
  padding-bottom: 5px;
  left: var(--sidebar-width);
  transition: var(--toggle-in);
}

/*POPUP*/
#sidebar {
  z-index: var(--popup-index);
  height: 100%;
  padding: 0;
  top: 0;
  left: 0;
  width: var(--sidebar-width);
  transform: translateX(-100%);
  /*CHANGE THIS TO TURN OFF TOGGLE*/
  display: flex;
  flex-direction: column;
  justify-content: flex-start;
}

#sidebar.active {
  transform: translateX(0);
}

/*sidebar active*/
#sidebarToggle.active {
  top: 0;
  left: var(--sidebar-width);
}

#sidebarToggle.active svg #close {
  position: absolute;
  top: 0;
  left: 0;
  opacity: 1;
  display: block;
}


/*SIDEBAR STYLING*/

.sidebar-box {
  box-sizing: border-box;
  justify-content: flex-start;
  display: flex;
  flex-direction: column;
  background-color: #031842;
}

#logo {
  height: var(--sidebar-logo-height);
  padding: 50px;
  justify-content: center;
  align-content: center;
  background-color: #031842;
}

#main-menu {
  height: calc((100vh - var(--sidebar-logo-height)) / 2);
  padding: 20px;
  background-color: #031842;
}

#sidebar-search {
  height: calc((100vh - var(--sidebar-logo-height)) / 4);
  background-color: #031842;
}

#login {
  width: 100%;
  margin: 0;
  justify-content: center;
  height: calc((100vh - var(--sidebar-logo-height)) / 4);
  background-color: #031842;
}

/*==================LOGO======================*/
#logo #animated-logo {
  margin: 0;
  transition: var(--short-in-out);
}

#logo #animated-logo:hover {
  transform: scale(1.05);
  transition: var(--short-in-out);
}


/*=================MENU==================*/

#main-menu ul {
  list-style: none;
  padding: 0;
  margin: 0;
}

/*main menu li items*/
.menuitem {
  margin: 5px;
  display: flex;
  justify-items: flex-start;
  flex-direction: column;
  position: relative;
  height: var(--menuitem-height);
}

/*toggle input for submenus*/
.subtoggle {
  height: var(--menuitem-height);
  padding: 0;
  margin: 0;
  width: 100%;
  cursor: pointer;
  top: 0;
  left: 0;
  position: absolute;
  z-index: 10;
  opacity: 0;
}

/*submenu label*/
/* #aboutLabel {
  opacity: 1;
  position: absolute;
  font-family: var(--new-order);
  color: #fffdf7;
  font-size: 1.333rem;
  font-weight: 300;
  text-transform: uppercase;
  letter-spacing: .05em;
  margin: 0;
  text-align: left;
  transition: var(--menuitem-out);
} */

/* #about:hover ~ #aboutLabel,
#aboutToggle:hover ~ #aboutLabel {
  opacity: 0;
} */
#homeLink,
#joinLink,
.sublabel {
  position: relative;
  font-family: var(--new-order);
  color: #fffdf7;
  font-size: 1.428rem;
  line-height: 2em;
  font-weight: 300;
  text-decoration: none;
  text-transform: uppercase;
  letter-spacing: .05em;
  margin: 0;
  text-align: center;
  transition: var(--menuitem-out);
  z-index: 1;
}

#homeLink:hover,
#joinLink:hover,
.submenu:hover~.sublabel,
.subtoggle:hover~.sublabel {
  color: #fed318;
  letter-spacing: .1em;
  transition: var(--menuitem-in);
}

/* .menuitem:hover label,
.menuitem:hover input {
  z-index: -1;
} */

/* .submenu ul .menuitem>a {
  color: #d72b88;
} */

/* .subtoggle {
  z-index: 10;
  width: 100%;
  height: 100%;
  opacity: 0;
} */

/*SUBMENU*/
.submenu {
  display: flex;
  z-index: -1;
  margin: 0;
  position: fixed;
  background-color: #031842;
  margin-top: var(--sidebar-logo-height);
  width: calc(var(--sidebar-width) * 1);
  padding: 1rem 1rem 1rem .25rem;
  opacity: 0;
  left: -2rem;
  border-radius: var(--left-br);
  top: 0;
  transition: var(--submenu-out);
}

/* submenu reveal*/
.menuitem:hover .submenu,
.menuitem .submenu:hover,
#aboutToggle[type="checkbox"]:checked~#aboutSubmenu,
#advocacyToggle[type="checkbox"]:checked~#advocacySubmenu,
#membershipToggle[type="checkbox"]:checked~#membershipSubmenu,
#eventsToggle[type="checkbox"]:checked~#eventsSubmenu {
  left: 100%;
  opacity: 1;
  transition: var(--submenu-in);
}

/* 
#aboutToggle[type="checkbox"]:not(:checked)~#aboutSubmenu,
#advocacyToggle[type="checkbox"]:not(:checked)~#advocacySubmenu,
#membershipToggle[type="checkbox"]:not(:checked)~#membershipSubmenu,
#eventsToggle[type="checkbox"]::not(:checked)~#eventsSubmenu {

  left: 100%;
  opacity: 1;

  transition: var(--submenu-in);
} */

/* #aboutToggle[type="checkbox"]:checked~#aboutSubmenu,
#advocacyToggle[type="checkbox"]:checked~#advocacySubmenu,
#membershipToggle[type="checkbox"]:checked~#membershipSubmenu,
#eventsToggle[type="checkbox"]:checked~#eventsSubmenu {
  left: 100%;
  opacity: 1;
  transition: var(--submenu-in);
} */

#aboutSubmenu {
  top: calc(var(--menuitem-height) + 0);
}

#membershipSubmenu {
  top: calc(var(--menuitem-height) * 2 + 1.25rem);
}

#advocacySubmenu {
  top: calc(var(--menuitem-height) * 3 + 2.5rem);
}

#eventsSubmenu {
  top: calc(var(--menuitem-height) * 4 + 1rem);
}

/*submenu parent list items*/

#aboutLink span,
#membershipLink span,
#advocacyLink span,
#eventsLink span {
  font-size: 1.33rem;
  color: #fed318 !important;
  font-family: 'new-order', sans-serif;
  text-transform: capitalize;
  line-height: 1.5;
  text-decoration: none !important;
  letter-spacing: 0;
  font-weight: 300;
  transition: var(--menuitem-out);
}

#aboutLink:hover span,
#membershipLink:hover span,
#advocacyLink:hover span,
#eventsLink:hover span {
  letter-spacing: .5px;
  color: #d72b88 !important;
  transition: var(--menuitem-in);
}

/*submenu child list items*/
.submenu .submenuitem>a {
  font-family: var(--new-order);
  color: #fffdf7;
  font-size: 1.2rem;
  line-height: 1.7;
  font-weight: 200;
  letter-spacing: 0;
  text-decoration: none;
  padding: 5px 0 0 2px;
  text-transform: capitalize;
  text-align: right;
  transition: var(--menuitem-out);
}

.menuitem .submenuitem:hover>a {
  color: #fed318;
  letter-spacing: .5px;
  padding: 5px 0 0 5px;
  border-left: solid 1px #fffdf7;
  transition: var(--menuitem-in);
}




/*=================SEARCH============================ */

#sidebar-search form {
  z-index: 1;

  box-sizing: border-box;
  margin: auto;
  position: relative;
  width: 3rem;
  height: 3rem;
  background: transparent;
  border-radius: 50%;
  border: calc(var(--outline-width) * 2) solid #fffdf7;
  border-width: var(--outline-width);
  transition: var(--short-out);
  transition-delay: 1000ms;
}

#sidebar-search form input {
  font-family: 'new-order', serif;
  position: absolute;
  font-weight: 400;
  color: #243f76;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  font-size: 1rem;
  border: none;
  padding: .2rem;
  opacity: 0;
  transition: var(--short-out);
  transition-delay: 1000ms;
  z-index: 0;
}

#sidebar-search svg {
  box-sizing: border-box;
  width: 1.5rem;
  height: 1.5rem;
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  text-align: center;
  transition: var(--short-out);
  transition-delay: 1000ms;
}

#sidebar-search svg path {
  fill: #fffdf7;
  transition: var(--short-out);
  transition-delay: 1000ms;
}

#sidebar-search input::-webkit-search-cancel-button {
  position: relative;
  right: 20px;
  -webkit-appearance: none;
}

#sidebar-search form:hover,
#sidebar-search form:valid,
#sidebar-search form:focus {
  box-sizing: border-box;
  width: 100%;
  cursor: pointer;
  border-radius: 0;
  border: calc(var(--outline-width) * 2) solid #001226;
  opacity: 1;
  transition: all 200ms ease-in, width 300ms ease-in 200ms;

}

#sidebar-search form:focus input,
#sidebar-search form:hover input,
#sidebar-search form:valid input {
  font-family: 'new-order', serif;
  font-weight: 400;
  display: block;
  border: none;
  border-radius: 0%;
  color: #243f76;

  opacity: 1;
  transition: var(--short-in), width 300ms ease-in 200ms;
  padding: 0 5px;
  background-color: rgba(255, 253, 247, 1);

}

#sidebar-search form:hover svg,
#sidebar-search form:valid svg {
  left: 92%;
  transition: var(--short-in)
}

#sidebar-search form:hover svg path,
#sidebar-search form:valid svg path {
  fill: #001226;
  transition: var(--short-in)
}

#sidebar-search *:focus {
  outline: none;
}

#sidebar-search form svg:hover {
  width: 1.75rem;
  transition: all 200ms ease-in, width 300ms ease-in 200ms;
}

/* === login * ===*/

#login a {
  padding: 15px 0;
  text-align: center;
  text-transform: uppercase;
  font-weight: 300;
  box-shadow: var(--btn-box-shadow);
  border-radius: 0;
  margin: 0;
  font-size: 1rem;
  letter-spacing: 1px;
  font-family: var(--new-order);
  color: #fffdf7 !important;
  transition: var(--btn-out), box-shadow 200ms ease 200ms;
  text-decoration: none;

}

#login:hover a {
  font-weight: 400;
  text-align: center;
  color: #001226 !important;
  font-weight: 500;
  letter-spacing: 3px;
  box-shadow: var(--btn-hover-box-shadow);
  background-color: #fffdf7;
  transition: var(--btn-out), box-shadow 200ms ease 200ms;

}

/* =============== MOBILE HEADER =============== */
@media only screen and (max-width: 640px) {

  #floatingCalendar {
    position: fixed;
    top: calc(var(--toggle-width) * 1 + 1rem);
    left: 0;
    z-index: 5;
  }

  #floatingSearch {
    position: fixed;
    left: 0;
    top: calc(var(--toggle-width) * 2 + 2.5rem);
  }

  #floatingLogin {
    position: fixed;
    left: 0;
    top: calc(var(--toggle-width) * 3 + 3rem);
    z-index: 4;
  }

  /*popups*/
  .popup {
    z-index: -1;
  }

  .popup.active {
    z-index: 1;
  }

  /*====TOGGLES===*/

  /*SIDEBAR*/
  #sidebarToggle {
    transform: translate(5px, 0);
  }

  /*CALENDAR*/
  #calendarToggle {
    position: fixed;
    top: calc(var(--toggle-width) * 1 + 1rem);
    left: 5px;
    z-index: 5;
    opacity: 0;
    transform: translate(-100%, 0);
    transition: var(--toggle-out);
  }

  #calendarToggle.shift {
    position: fixed;
    top: calc(var(--toggle-width) * 1 + 1rem);
    left: calc(var(--sidebar-width) + 5px);
    opacity: 1;
    transform: translate(0, 0);
    transition: var(--toggle-in);
    transition-delay: 200ms;
  }

  /*SEARCH*/
  #searchToggle {
    position: fixed;
    top: calc(var(--toggle-width) * 2 + 3rem);
    left: 12px;
    opacity: 0;
    transform: translate(-120%, 0);
    transition: var(--toggle-out);
  }

  #searchToggle.shift {
    position: fixed;
    transform: translate(0, 0);
    left: calc(var(--sidebar-width) + 12px);
    opacity: 1;
    transition: var(--toggle-in);
    transition-delay: 250ms;
  }

  #searchToggle.active {
    top: 15px;
    transform: translate(0, 0);
    left: calc(100vw - var(--toggle-width) - 5px);
  }

  /*LOGIN*/
  #loginToggle {
    position: fixed;
    top: calc(var(--toggle-width) * 3 + 40px);
    left: 5px;
    z-index: 4;
    opacity: 0;
    transform: translate(-100%, 0);
    transition: var(--toggle-out);

  }

  #loginToggle.shift {
    position: fixed;
    left: calc(var(--sidebar-width) + 5px);
    opacity: 1;
    transition: var(--toggle-in);
    transform: translate(0, 0);
    transition-delay: 300ms;
  }

  #loginToggle.active {
    top: 5px;
    left: calc(100vw - var(--toggle-width) - 5px);
    transform: translate(0, 0);
    transition-delay: 0;
  }

  /*TEXT*/
  .toggle.shift .text {
    position: fixed;
    border-radius: 5px;
    text-align: center;
    margin: auto;
    opacity: 0;
    width: fit-content;
    bottom: 0;


    padding: 5px 2px 2px 2px;
    border-radius: 3px;
    transition: var(--label-out), var(--opacity-instant);
  }



  .shift.active .text,
  .active .text {
    opacity: 0;
    transition: none;
  }

  .toggle:hover .text {
    opacity: 1;
    transition: var(--label-drop);
  }

  .toggle.active:hover .text {
    opacity: 0;
  }

  .toggle.shift .text,
  .toggle:hover .text {
    opacity: 1;
    transform: scale(1);
    bottom: -5rem;
    transition: var(--label-drop);
    transform: translate(0, 0);
    left: 0;
  }


  .toggle span {
    color: #001226;
    opacity: 1;
    text-transform: uppercase;
    font-family: var(--new-order);
    font-weight: 600;
    font-size: 18px;
    padding: 5px 5px 2px 5px;
    border-radius: 3px;
  }

  #sidebarToggle:hover .text {
    bottom: 0;
  }

  #calendarToggle.shift .text {
    width: fit-content;
    height: fit-content;
    transform: translate(0, 10px);
    top: 0;
    padding: 5px 5px 2px 0px;
  }

  #calendarToggle.shift:hover .text {
    width: fit-content;
    top: 0;
    right: 0;
    padding: 5px 5px 2px 0px;
    transform: translate(0, 10px);
  }

  #searchToggle.shift .text {
    width: fit-content;
    height: fit-content;
    bottom: -30%;
    left: 0;
    transform: translate(-10px, 0px);
    text-align: left !important;
  }

  #searchToggle.shift:hover .text {
    width: fit-content;
    transform: translate(0px, 0px);
    padding: 5px 5px 2px 0px;
  }

  #loginToggle.shift .text {
    width: fit-content;
    height: fit-content;
    bottom: 0;
    transform: translate(0, 100%);
    padding: 5px 5px 2px 0px;
  }

  #loginToggle.shift:hover .text {
    width: fit-content;
    padding: 5px 5px 2px 0px;
    transform: translate(0, 0);
  }

  #calendarToggle.active .text,
  #loginToggle.active .text,
  #searchToggle.active .text {
    opacity: 0;
    transition: none;
  }

  /*popups*/
  #calendarPopup {
    top: 0;
    left: 0;
    transform: translate(-100%, 0);
  }

  #calendarPopup.active {
    z-index: 1;
    transform: translate(0, 0);
  }

  #loginPopup.active {
    top: 0;
    right: 0;
  }

  /* MOBILE SIDEBAR */
  #sidebar-box {
    height: fit-content;
  }

  #logo {
    height: calc(var(--sidebar-logo-height) + 40px);

  }

  /* MOBILE LOGO */
  #animated-logo {
    margin: auto;
    width: 100%;
    height: var(--sidebar-logo-height);
    padding-top: 10px;
    transition: var(--short-in-out);
  }

  #animated-logo:hover {
    transform: scale(1.05);
    transition: var(--short-in-out);
  }

  /* MOBILE MENU */
  #homeLink,
  #joinLink {

    text-align: right;
  }

  .subtoggle {
    opacity: 0;
    height: calc(var(--menuitem-height) * 2);
    padding: 3px;
    margin: 2px;
  }

  .menuitem .sublabel {
    top: 0;
    left: 0;
    text-align: right;
  }

  .menuitem {
    height: fit-content;
    text-align: right;
    z-index: 0;
  }


  .menuitem input[type="checkbox"]:not(:checked)~label {
    z-index: -1;
  }

  .menuitem input[type="checkbox"]:not(:checked) {
    z-index: 1;
  }

  .menuitem input[type="checkbox"]:checked~a {
    z-index: 1;
  }

  .menuitem input[type="checkbox"]:checked~.menuitem input,
  .menuitem input[type="checkbox"]:checked~.menuitem label {
    z-index: -1;
  }

  .menuitem>a {
    text-align: right;
    font-size: 28px;
    line-height: 40px;
  }

  .submenuitem>a {
    font-size: 1rem;
    font-weight: 100;
    letter-spacing: 0;
    text-align: right;
  }

  .menuitem:hover>a {
    color: #fed318;
    letter-spacing: .1em;
  }

  .menuitem .submenuitem:hover>a {
    border-left: solid 0px #fffdf7;
  }

  /*SUBMENU*/

  .submenu ul {
    width: 100%;
    margin: 0px 10px 20px 0 !important;
    padding-right: 5px !important;
    border-right: solid 1px white;
    position: relative;
  }

  .submenu,
  .menuitem:hover .submenu,
  .menuitem .submenu:hover {
    opacity: 0;
    z-index: 0;
    margin: 0;
    position: relative;
    width: 100%;
    padding: 0;
    height: 0;
    left: -100%;
    top: 0;
  }

  #aboutToggle[type="checkbox"]:not(:checked)~#aboutSubmenu,
  #advocacyToggle[type="checkbox"]:not(:checked)~#advocacySubmenu,
  #membershipToggle[type="checkbox"]:not(:checked)~#membershipSubmenu,
  #eventsToggle[type="checkbox"]::not(:checked)~#eventsSubmenu {
    opacity: 0;
    height: 0;
    padding: 0 5px;
    margin: 10px 10px 20px 0;
    left: 10px;
  }

  #aboutToggle[type="checkbox"]:checked~#aboutSubmenu,
  #advocacyToggle[type="checkbox"]:checked~#advocacySubmenu,
  #membershipToggle[type="checkbox"]:checked~#membershipSubmenu,
  #eventsToggle[type="checkbox"]:checked~#eventsSubmenu {
    opacity: 1;
    height: fit-content;
    left: 0;
  }

  /* #aboutSubmenu,
  #membershipSubmenu,
  #advocacySubmenu,
  #eventsSubmenu {
    top: 0 !important;
  } */

  .homeLink,
  #joinLink,
  .sublabel {

    text-align: right;
  }

  #searchPopup {
    position: fixed;
    width: 0;
    border-radius: 3px;
    left: 100%;
    background-color: #031842;
    padding: 10px;
    margin: 10px var(--toggle-width) 0 10px;
  }

  #searchPopup.active {
    left: 0;
    width: calc(100vw - var(--toggle-width) * 1.5);
    border-radius: 3px;
    background-color: #031842;
    padding: 10px;
    margin: 10px var(--toggle-width) 0 10px;
  }

  /*SEARCH*/
  #searchPopup form {
    position: relative;
    height: 3rem;
    width: 100%;
    left: 0;
    border-color: #fffdf7;
    border-width: 1px;
  }

  /*hide sidebar search & login */
  #login,
  #sidebar-search {
    display: none;
  }
}

/* --- end header --- */

.background-noise {

  position: fixed;
  top: -50%;
  left: -50%;
  right: -50%;
  bottom: -50%;
  width: 200%;
  height: 200vh;
  background: transparent url('http://assets.iceable.com/img/noise-transparent.png') repeat 0 0;
  background-repeat: repeat;
  animation: bgNoise .2s infinite;
  opacity: .9;
  visibility: visible;
}

@keyframes bgNoise {
    0% { transform: translate(0,0) }
    10% { transform: translate(-5%,-5%) }
    20% { transform: translate(-10%,5%) }
    30% { transform: translate(5%,-10%) }
    40% { transform: translate(-5%,15%) }
    50% { transform: translate(-10%,5%) }
    60% { transform: translate(15%,0) }
    70% { transform: translate(0,10%) }
    80% { transform: translate(-15%,0) }
    90% { transform: translate(10%,5%) }
    100% { transform: translate(5%,0) }

}

@import url("https://use.typekit.net/xcu6jyb.css");

:root {
    --sg-font: "allotrope-variable", sans-serif;
    --sg-font-var: "wght" 100, "wdth" 50;
    --sg-nav-li-var: "wght" 100, "wdth" 60;
    --sg-color-var: "wght" 100, "wdth" 40;
    --sg-body-var: "wght" 150, "wdth" 80;
    --sg-specs-var: "wght" 100, "wdth" 50;
}

.sg,
.sg:hover {
    color: #fff;
    font-family: var(--sg-font);
    font-variation-settings: var(--sg-font-var);
    text-align: center;
    transition: all 500ms ease-in-out 200ms;
}

.sg:hover {
    opacity: .5;
    transition: all 500ms ease-in-out 200ms;
}

/* ===== FONT BOXES ===== */

.font-box {
    display: flex;
    flex-direction: column-reverse;
    gap: 0;
    width: 100%;
    overflow: visible;
}

.font-box .specs {
    opacity: 0;
    transform: translate(-100%, 0);
    transition: 500ms ease-in-out 200ms;
}

.font-box:hover .specs {
    opacity: .5;
    transform: translate(0, 0);
    transition: 500ms ease-in-out 200ms;
}

#display-headings {

    text-align: right;
}

#display-headings .font-box .specs {
    text-align: right;
    transform: translate(100%, 0);
    transition: 500ms ease-in-out 200ms;
}

#display-headings .font-box:hover .specs {
    transform: translate(0, 0);
    transition: 500ms ease-in-out 200ms;
}

.blockquote .specs {
    text-align: center;
    width: 100%;
}

/* specs */
.font-box .specs .spec {
    color: #fff;
    position: relative;
    opacity: 0;
    bottom: 0;
    font-size: 1rem;
    transition: 500ms ease-in-out 200ms;
}

.font-box:hover .specs .spec {
    opacity: 1;
    transition: 500ms ease-in-out 200ms;
}

.font-box .specs .spec svg {
    height: .8em;
    margin: 10px 5px;
    fill: #ffffff;
}

.font-box img {
    max-width: 300px;
}

.left {
    position: relative;
    left: 0;
    text-align: left;
}

/* ===== COLOR BOXES ===== */
.palette {
    gap: 2vw;
    z-index: 1;
}

.palette .color {
    transform-origin: center;
    height: 150px;
    width: 150px;
    text-align: center;
    z-index: 1;
    margin: 2px 2px 20px 2px;
    position: relative;
    border-radius: 50%;
    box-shadow: rgba(149, 157, 165, 0.1) 0px 2pxpx 2px 2px;
    -webkit-animation: slide-in-fwd-center 0.4s cubic-bezier(0.250, 0.460, 0.450, 0.940) both;
    animation: slide-in-fwd-center 0.4s cubic-bezier(0.250, 0.460, 0.450, 0.940) both;
    transition: all 500ms ease-in-out 200ms;
}

#primary .color {
    height: 175px;
    width: 175px;

}

.palette .color:hover {
    box-shadow: rgba(0, 0, 0, 0.56) 0px 10px 200px 200px;
    transform: scale(1.33);
    border-radius: 2%;
    z-index: 100;
    -webkit-animation: slide-in-fwd-center 1000ms cubic-bezier(0.250, 0.460, 0.450, 0.940) both 200ms;
    animation: slide-in-fwd-center 1000ms cubic-bezier(0.250, 0.460, 0.450, 0.940) both 200ms;
    transition: all 500ms ease-in-out 200ms;
}

/* specs */
.color .spec {
    font-size: 1rem;
    margin: 2px 0;
    transform: translate(0, -50%);
    opacity: 0;
    transition: all 500ms ease-in-out 200ms;
}

.color:hover .spec {
    opacity: 1;
    transform: translate(0, 0);
}

/* color names */
.color .name {
    opacity: 0;
    text-transform: uppercase;
    transition: all 500ms ease-in-out 200ms;
}

.color:hover .name {
    opacity: 1;
    transition: all 500ms ease-in-out 200ms;
    transition-delay: 50ms;
}

/* role */
.color .role {
    opacity: 0;
    transition: all 500ms ease-in-out 200ms;
}

.color:hover .role {
    opacity: 1;
}

