/* header */
:root {
    --toggle-width: 70px;
    --toggle-height: 60px;
    --left-br: 0 6px 6px 0;
    --right-br: 6px 0 0 6px;
    --top-right-br: 0 0 0 6px;
    --top-left-br: 0 0 6px 0;
    /*z-index*/
    --float-index: 1000;
    --popup-index: 1000;
    --toggle-index: 100;
    --outline-width: 1px;
    --opacity-instant: opacity 50ms linear;
    --toggle-out: all 300ms cubic-bezier(0.77, 0, 0.175, 1), letter-spacing 500ms ease-out 100ms;
    --toggle-in: all 600ms cubic-bezier(0.77, 0, 0.175, 1) 100ms, letter-spacing 200ms ease-in 100ms;
}

#menuWrap {
    position: fixed;
    width: fit-content;
    display: flex;
    flex-direction: column;
    justify-content: flex-start;
    align-content: right;
    top: 0;
    left: 0;
    border-radius: 5px;
    z-index: var(--float-index);
}

#menuToggle {
    padding: 5px;
    cursor: pointer;
    z-index: var(--toggle-index);
    height: var(--toggle-height);
    width: var(--toggle-width);
    transition: var(--toggle-out);

    position: absolute;
    top: 0;
    left: 0;
}

#menu {
    box-sizing: border-box;
    position: fixed;
    background-color: #031842;
    transition: var(--toggle-out);

    height: auto;
    width: 100%;
    top: 0;
    left: 0;
    padding: 15px 0 15px 15px;
    z-index: 1;
    border-radius: 0 0 0 5px;
    transform: translate(-100%, 0);
    transition: var(--toggle-out);
}

#menu.active {
    transform: translate(0, 0);
}

#menu h1 {
    font-size: 2rem;
}

#menu svg path {
    fill: white;
}

function menuToggle() {
    var menu = document.getElementById('menu');
    var menuToggle = document.getElementById('menuToggle');

    //popup
    if (menu.className === 'popup') {
        menu.className += ' active';
    } else {
        menu.className = 'popup';
    }
    //toggle
    if (menuToggle.className === 'toggle') {
        menuToggle.className += ' active';
    } else if (menuToggle.className === 'toggle shift') {
        menuToggle.className += ' active';
        overlay.className = 'show';

        sidebarToggle.className = 'toggle';
        sidebar.className = 'popup';

        calendarToggle.className = 'toggle';
        calendarPopup.className = 'popup';

        loginToggle.className = 'toggle';
        loginPopup.className = 'popup';
    } else {
        menuToggle.className = 'toggle';
    }


}

