/* ANIMATIONS */

h1 {
    animation-name: focus-in-expand-fwd;
    animation-duration: 2s, 5s;
    animation-iteration-count: 1, 5;
    animation-timing-function: cubic-bezier(0.250, 0.460, 0.450, 0.940);
    animation-fill-mode: both, alternate;
}

h2 {
    animation-name: focus-in-expand-fwd;
    animation-duration: 2s, 5s;
    animation-iteration-count: 1, 5;
    animation-delay: 500ms, 5s;
    animation-timing-function: cubic-bezier(0.250, 0.460, 0.450, 0.940);
    animation-fill-mode: both, alternate;

    animation: focus-in-expand-fwd .75s cubic-bezier(0.250, 0.460, 0.450, 0.940) both;
}

h3 {
    animation-name: focus-in-expand-fwd;
    animation-duration: 2s, 5s;
    animation-iteration-count: 1, 5;
    animation-timing-function: cubic-bezier(0.250, 0.460, 0.450, 0.940);
    animation-fill-mode: both, alternate;


    animation: focus-in-expand-fwd 0.6s cubic-bezier(0.250, 0.460, 0.450, 0.940) both;
}

h4 {
    animation-name: focus-in-expand-fwd;
    animation-duration: 2s, 5s;
    animation-iteration-count: 1, 5;
    animation-timing-function: cubic-bezier(0.250, 0.460, 0.450, 0.940);
    animation-fill-mode: both, alternate;


    animation: focus-in-expand-fwd 0.5s cubic-bezier(0.250, 0.460, 0.450, 0.940) both;
}

h5 {
    animation-name: focus-in-expand-fwd;
