  right: 0;
  margin: auto;
  width: 10vmax;
  height: 10vmax;
  background: #222;
  z-index: 999;
  border-radius: 50%;
  overflow: hidden;
  text-align: center;
  line-height: 10vmax;
  font-family: -apple-system, system-ui, BlinkMacSystemFont, sans-serif;
  font-size: 1.5vmax;
  letter-spacing: 0.125em;
  font-weight: bold;
  text-transform: uppercase;
  color: #fff;
}
#button:before {
  content: ".";
  letter-spacing: 0;
  visibility: hidden;
}
#button:hover {
  background: #000;
  cursor: pointer;
}
#button:hover ~ #overlay {
  transform: scale3d(1.5, 1.5, 1);
}

