var coolform = angular.module('coolform', []);
coolform
  .directive('coolForm', function($timeout) {
    var ctrl = function($scope, $element, $attributes) {
      $scope.questions = [];
      $scope.activequestion = -1;
      $scope.answering = true;

      $scope.questions.push({'question': 'What\'s your name?'});
      $scope.questions.push({'question': 'How old are you?'});
      $scope.questions.push({'question': 'Where do you live?'});

      function removeOpen() {
        for(i=0;i<qs.length;i++){
          angular.element(qs[i]).removeClass('open');
        }
      }

      var scrolle = document.getElementById('form-wrapper');
      var qs = document.getElementsByClassName('question');

      $scope.open = function(order) {
        removeOpen();
        if (order >= $scope.questions.length || order < 0) {
          $scope.answering = false;
          if ($element.hasClass('answering')) {
            $element.removeClass('answering');
            $scope.activequestion = $scope.questions.length+1;
          }
        } else {
          $scope.answering = true;
          if (!$element.hasClass('answering')) {
            $element.addClass('answering');
          }
          //document.activeElement.blur();
          $scope.activequestion = order;
          var offset = qs[0].offsetTop;
          if(order !== 0) {offset = qs[order-1].offsetTop;}
          scrollToAndFocus(scrolle, offset, 500, order);
          if (!angular.element(qs[order]).hasClass('open')) {
            angular.element(qs[order]).addClass('open');
          }
        }

      }

      function scrollToAndFocus(element, to, duration, focus) {
          if (duration <= 10) {
            document.getElementById('q'+(focus)).focus();
            return;
          }
          var difference = to - element.scrollTop;
          var perTick = difference / duration * 10;
          window.setTimeout(function() {
              element.scrollTop = element.scrollTop + perTick;
              if (element.scrollTop === to) return;
              scrollToAndFocus(element, to, duration - 10, focus);
          }, 10);
      }


      var handler = function(e){
        if(e.keyCode === 37) {
          //left arrow
          e.preventDefault(); 
          $scope.$apply(function() {
            $scope.open($scope.activequestion-1);
          });
        }     
        if(e.keyCode === 39) {
          //right arrow
          e.preventDefault(); 
          $scope.$apply(function() {
            $scope.open($scope.activequestion+1);
          });
        }
        if(e.keyCode === 13) {
          //enter
          e.preventDefault(); 
          $scope.$apply(function() {
            $scope.open($scope.activequestion+1);
          });
        }
        if (e.keyCode == 9) {
          //tab
          e.preventDefault(); 
          $scope.$apply(function() { $scope.open($scope.activequestion+1);
          });
        } 
      };


      $element.on('keydown', handler);
      $scope.$on('$destroy',function(){
        $element.off('keydown', handler);
      });


      setTimeout(function() {
        $scope.activequestion++;
        $scope.$apply(function(){
          $scope.open($scope.activequestion);
        });
      }, 2000);
    };
    return {
      restrict: 'EA',
      replace: true,
      transclude: true,
      link: ctrl,
      template: '<div ng-transclude id="form-wrapper" class="answering"></div>'
    };

  });

:root {
  --color-primary: #24e1ce;
  --color-secondary: #1563ff;
  --color-gray: #333333;
  --color-white: #fff;
}

*,
*:after,
*:before {
  margin: 0;
  padding: 0;
  box-sizing: inherit;
}

html {
  font-size: 62.5%;
  box-sizing: border-box;
}

body {
  font-family: "Gill Sans", "Gill Sans MT", Calibri, "Trebuchet MS", sans-serif;
  color: var(--color-white);
  background-color: var(--color-gray);
  font-size: 1.8rem;
}

form {
  width: max-content;
  margin: 0 auto;
  padding-top: 4rem;
}

legend {
  font-weight: 500;
}

fieldset {
  border: 0;
  margin: 0;
  min-width: 0;
}

.checkboxes-container {
  clear: both;
  position: relative;
  padding: 4rem 2rem;
  display: flex;
  flex-direction: column;
  gap: 2rem;
}

.option {
  display: flex;
  flex-direction: row-reverse;
  align-items: center;
  justify-content: flex-end;
  gap: 2rem;
  cursor: pointer;
  font-size: 1.6rem;
  color: var(--color-white);
  -webkit-user-select: none;
  -moz-user-select: none;
  -ms-user-select: none;
  user-select: none;
}

.option input {
  position: absolute;
  opacity: 0;
  cursor: pointer;
}

.checkbox {
  position: relative;
  height: 28px;
  width: 28px;
  background-color: transparent;
  border: 1px solid var(--color-white);
  transition: all 0.15s;
}

.option input:focus-visible ~ .checkbox {
  border: 1px solid var(--color-primary);
}

.option:hover input ~ .checkbox {
  border: 1px solid var(--color-primary);
}

/* ---------- */
/* Checkbox 1 */

.checkbox1:after {
  content: "";
  position: absolute;
  top: 13px;
  left: 3px;
  width: 0px;
  height: 0px;
  border: solid var(--color-secondary);
  border-width: 2px 2px 0 0;
  opacity: 0;
  transform-origin: left top;
  transform: scaleX(-1) rotate(135deg);
  transition: width 0.08s ease 0.1s, height 0.1s ease, border-color 0.3s ease,
    opacity 0.1s ease 0.2s, border-width 0.1s ease;
}

.option input:checked ~ .checkbox1:after {
  opacity: 1;
  width: 10px;
  height: 18px;
  border-color: var(--color-primary);
  transition: width 0.1s ease, height 0.08s ease 0.1s, border-color 0.3s ease,
    border-width 0.1s ease;
}

/* ---------- */
/* Checkbox 2 */

.checkbox2:after {
  content: "";
  position: absolute;
  left: -3px;
  top: -3px;
  width: 2px;
  height: 2px;
  background-color: var(--color-gray);
  transition: all 0.15s;
}

.option input:checked ~ .checkbox2 {
  left: 6px;
  top: 2px;
  width: 12px;
  height: 20px;
  margin: 0 14px 8px 2px;
  border: solid var(--color-primary);
  border-width: 0 1px 1px 0;
  transform: rotate(45deg);
}

.option input:checked ~ .checkbox2:after {
  display: block;
  left: -4px;
  top: 2px;
  width: 2px;
  height: 2px;
  transform: scale(9);
}

.option input:checked:hover ~ .checkbox2,
.option input:checked:focus ~ .checkbox2 {
  border-width: 0 2px 2px 0;
}

/* ---------- */
/* Checkbox 3 */

.checkbox3:after {
  content: "";
  position: absolute;
  top: 14px;
  left: 12px;
  width: 0px;
  height: 0px;
  border: solid;
  border-width: 2px 2px 0 0;
  opacity: 0;
  transform: scaleX(-1) rotate(135deg);
  animation: unchecked 0.15s ease-in;
}

.option input:checked ~ .checkbox3:after {
  opacity: 1;
  top: 2px;
  left: 8px;
  width: 10px;
  height: 18px;
  border-color: var(--color-primary);
  transform: scaleX(-1) rotate(135deg);
  animation: checked 0.3s;
}

@keyframes checked {
  0% {
    top: 2px;
    left: 8px;
    width: 0px;
    height: 0px;
    opacity: 0;
    border-color: var(--color-secondary);
    transform: scaleX(-1) rotate(135deg);
  }
  10% {
    width: 2px;
    height: 18px;
  }
  50% {
    border-color: var(--color-secondary);
    transform: scale(300%) scaleX(-1) rotate(135deg);
  }
  100% {
    width: 10px;
    height: 18px;
    opacity: 1;
    border-color: var(--color-primary);
    transform: scale(100%) scaleX(-1) rotate(135deg);
  }
}

@keyframes unchecked {
  0% {
    top: 2px;
    left: 8px;
    width: 10px;
    height: 18px;
    opacity: 1;
    border-width: 2px 2px 0 0;
    border-color: var(--color-white);
  }
  20% {
    opacity: 1;
  }
  50% {
    opacity: 0.1;
  }
  100% {
    top: -15px;
    left: 0px;
    width: 30px;
    height: 40px;
    border-width: 15px 15px 0 0;
    opacity: 0;
  }
}

