/* FORMS */
button,
input,
optgroup,
select,
keygen::-webkit-keygen-select,
select[_moz-type="-mozilla-keygen"],
textarea {
    color: inherit;
    font: inherit;
    margin: 0;
    margin-top: 0.5em;
}

label {
    display: block;
    margin: 0.75em 0;
    font-family: var(--body2);
}

input[type="radio"]+label,
input[type="checkbox"]+label {
    margin: 0;
}

button,
input[type=button],
input[type=reset],
input[type=submit] {
    cursor: pointer;
}

button[disabled],
input[disabled] {
    cursor: default;
}

input {
    line-height: normal;
}

textarea {
    line-height: 1.25em;
}

select {
    background-color: #fff;
}

input[type=checkbox],
input[type=radio] {
    box-sizing: border-box;
