#twirlicons {
    --width: 1rem;
    --half: .5rem;
    --fortythree: .43rem;
    --fiftyseven: .57rem;
}

.twirl {
    width: 168px;
    height: 168px;
    position: relative;
    display: flex;
    flex-direction: column;
    flex-wrap: wrap;
    transform: scale(0.5);
    transform-origin: 50% 50%;
    transition: transform 0.4s ease;
}

.twirl .twirl-item {
    display: block;
    position: relative;
    width: 50%;
    padding-bottom: 50%;
    background: #270D40;
    -webkit-backface-visibility: hidden;
    transition: border-radius 0.3s ease, transform 0.2s ease;
}

.twirl .twirl-item svg {
    display: block;
    width: 100%;
    position: absolute;
    left: 0;
    top: 0;
    fill: #C93849;
    opacity: 0;
    transform: scale(0.6) rotate(-45deg);
    transition: all 0.15s ease;
    -webkit-backface-visibility: hidden;
}

.twirl a:nth-child(1) {
    border-radius: 16px 0 0 0;
}

.twirl a:nth-child(2) {
    border-radius: 0 0 0 16px;
}

.twirl a:nth-child(3) {
    border-radius: 0 16px 0 0;
}

.twirl a:nth-child(4) {
    border-radius: 0 0 16px 0;
}

.twirl:before,
.twirl:after {
    content: "";
    width: 40x;
    height: 24px;
    border-radius: 3px;
    background: #fff;
    position: absolute;
    left: 50%;
    top: 50%;
    display: block;
    z-index: 1;
    transform-origin: 50% 50%;
    transition: transform 0.25s ease;
}

.twirl:before {
    transform: translate(-50%, -50%) scaleY(0.76);
}

.twirl:after {
    transform: translate(-50%, -50%) rotate(90deg) scaleY(0.76);
}

.twirl:hover {
    transform: scale(1) rotate(45deg);
    transition: transform 0.4s ease 0.1s;
}

.twirl:hover:before {
    transform: translate(-50%, -50%) scaleY(0.76) scaleX(3);
}

.twirl:hover:after {
    transform: translate(-50%, -50%) rotate(90deg) scaleY(0.76) scaleX(3);
}

.twirl:hover .twirl-item {
    --scale: 1;
    pointer-events: none;
    border-radius: 50%;
    -webkit-animation: pointerEvent 0s linear forwards 0.4s;
    animation: pointerEvent 0s linear forwards 0.4s;
    transition: border-radius 0.15s ease 0.1s, transform 0.25s ease 0.15s;
}

.twirl:hover a:nth-child(1) {
    transform: translate(-12px, -12px) scale(var(--scale));
}

.twirl:hover a:nth-child(2) {
    transform: translate(-12px, 12px) scale(var(--scale));
}

.twirl:hover a:nth-child(3) {
    transform: translate(12px, -12px) scale(var(--scale));
}

.twirl:hover a:nth-child(4) {
    transform: translate(12px, 12px) scale(var(--scale));
}

.twirl:hover .twirl-item svg {
    opacity: 0.7;
    transition: all 0.3s ease 0.2s;
    transform: scale(1) rotate(-45deg);
}

.twirl:hover a:hover {
    --scale: .92;
    transition: border-radius 0.2s ease 0.1s, transform 0.25s ease 0s;
}

.twirl:hover a:hover svg {
    opacity: 1;
    transition: all 0.3s ease 0s;
}

@-webkit-keyframes pointerEvent {
    100% {
        pointer-events: auto;
    }
}

@keyframes pointerEvent {
    100% {
        pointer-events: auto;
    }
}

