    font-weight: 300;
    font-size: 3rem;
    opacity: .2;
    transition: var(--trans);
    transition-delay:0;
    animation-name: focus-in-expand-fwd;
    animation-duration: 500ms;
    animation-fill-mode: both;
}

#logotype:hover .letters {
    opacity: 1;
    font-size: 4rem;
